(()=>{let jobs=[],project='',loading=false,status=null;const labels={preparing:'准备中',queued:'排队中',running:'生成中',waiting:'等待输出',completed:'已完成',failed:'生成失败',cancelled:'已停止'},kinds={bgm:'背景音乐',song:'歌曲',ambience:'环境音',sfx:'动作音效',sync:'视频同步音效'};const busy=j=>['preparing','queued','running','waiting'].includes(j?.status);function config(shot,kind){shot.audioProduction??={};if(!shot.audioProduction[kind]){const track=data.shotScript?.global_audio?.music_tracks?.find(t=>(shot.audio?.bgm_references||[]).some(r=>r.track_id===t.track_id));const cues=kind==='ambience'?shot.audio?.ambience:kind==='sfx'?shot.audio?.sfx:[];shot.audioProduction[kind]={prompt:kind==='bgm'?(track?.generation?.prompt||track?.style_prompt||''):(cues||[]).map(c=>c.generation?.prompt||c.description).join('\n'),lyrics:'',duration:Number(shot.duration)||7,bpm:80,volume_db:kind==='bgm'?-12:-6};}return shot.audioProduction[kind];}
async function load(){if(loading||!data.project_id)return;loading=true;const id=data.project_id;try{const [items,s]=await Promise.all([frontFetch('/api/audio?project_id='+encodeURIComponent(id)),frontFetch('/api/audio/status')]);if(id===data.project_id){jobs=items;project=id;status=s;}}catch(e){if(typeof toast==='function')toast(e.message);}finally{loading=false;}}
function draw(shot,container){const kind=shot.audioProductionKind||'bgm',c=config(shot,kind),own=jobs.filter(j=>j.project_id===data.project_id&&j.target_id===(shot.shot_id||shot.id)&&j.kind===kind),running=own.find(busy),selected=own.find(j=>j.id===c.activeId)||own.find(j=>j.status==='completed'),canGenerate=['bgm','song'].includes(kind)?status?.ace?.ready:kind==='sync'?status?.mmaudio?.ready:status?.stable?.ready,model=['bgm','song'].includes(kind)?'ACE-Step 1.5 · 已下载':kind==='sync'?(status?.mmaudio?.message||'MMAudio · 模型与节点检查中'):(status?.stable?.message||'Stable Audio 3 · 模型与节点检查中');container.innerHTML='<h3>'+esc(shot.shot_id||shot.id)+' · 音乐与音效</h3><p class="subtle">音频跟随本分镜管理；采用后保留版本。原视频对白与原声单独保留。</p><fieldset style="border:0;padding:0;margin:16px 0"><legend>声音类别</legend><div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:10px">'+Object.entries(kinds).map(([id,name])=>'<label style="display:flex;align-items:center;gap:8px;padding:10px 14px;border:1px solid #3d5a53;border-radius:10px;cursor:pointer;background:'+(kind===id?'#203e35':'#15212d')+'"><input type="radio" name="shotAudioKind" value="'+id+'" '+(kind===id?'checked':'')+'> '+name+'</label>').join('')+'</div></fieldset><p class="subtle">'+esc(model)+'</p><label>音频提示词<textarea id="shotAudioPrompt" rows="4">'+esc(c.prompt)+'</textarea></label>'+(kind==='song'?'<label>歌词<textarea id="shotAudioLyrics" rows="5">'+esc(c.lyrics)+'</textarea></label>':'')+'<div style="display:flex;gap:12px;flex-wrap:wrap"><label>时长（秒）<input id="shotAudioDuration" type="number" min="1" max="180" step="0.1" value="'+c.duration+'"></label><label>节拍 BPM<input id="shotAudioBpm" type="number" min="10" max="300" value="'+c.bpm+'"></label><label>混音音量（dB）<input id="shotAudioVolume" type="number" min="-60" max="6" value="'+c.volume_db+'"></label></div>'+(kind==='sync'?'<p class="subtle">同步音效将引用本分镜当前采用的视频：'+esc(selectedShotVideo(shot)?.id||'尚未生成视频')+'</p>':'')+'<div style="display:flex;gap:12px;flex-wrap:wrap"><button id="shotAudioGenerate" class="primary" '+(!canGenerate||running?'disabled':'')+'>'+(running?'音频生成中…':'生成'+kinds[kind])+'</button>'+(running?'<button id="shotAudioStop">停止音频生成</button>':'')+'</div>'+(!canGenerate?'<p class="subtle">此类别尚未就绪，当前可先编辑并保存计划；模型及节点接入后启用生成。</p>':'')+(selected?'<p>当前试听：'+esc(kinds[kind])+'</p><audio controls preload="metadata" src="'+esc(selected.audio_url)+'" style="width:100%;margin:12px 0"></audio>':'')+'<div>'+own.map(j=>'<div style="padding:12px 0;border-top:1px solid #30404f"><b>'+esc(labels[j.status]||j.status)+' · '+j.duration+'秒</b>'+(j.elapsed_seconds?' · 耗时'+videoTime(j.elapsed_seconds):'')+(j.phase?'<p class="subtle">'+esc(j.phase)+'</p>':'')+(j.error?'<p>'+esc(j.error)+'</p>':'')+(!j.engine||j.engine==='comfy'?'<p><a target="_blank" rel="noopener" href="/api/open-workflow/'+j.id+'?kind=audio&port='+j.port+'">打开 ComfyUI 工作流 ↗</a></p>':'<p><a target="_blank" rel="noopener" href="http://127.0.0.1:'+j.port+'">打开 ComfyUI ↗</a> · 本条使用本机音频接口</p>')+(j.status==='completed'?'<audio controls preload="none" src="'+esc(j.audio_url)+'" style="width:100%;margin:8px 0"></audio><button data-audio-adopt="'+j.id+'">'+(c.activeId===j.id?'✓ 已采用':'采用此音频')+'</button>':'')+'</div>').join('')+'</div>';const q=id=>container.querySelector('#'+id);container.querySelectorAll('input[name=shotAudioKind]').forEach(el=>el.onchange=e=>{shot.audioProductionKind=e.target.value;save();draw(shot,container);});for(const [id,key]of [['shotAudioPrompt','prompt'],['shotAudioLyrics','lyrics'],['shotAudioDuration','duration'],['shotAudioBpm','bpm'],['shotAudioVolume','volume_db']]){const el=q(id);if(el)el.oninput=()=>{c[key]=['duration','bpm','volume_db'].includes(key)?Number(el.value):el.value;save();};}q('shotAudioGenerate').onclick=async e=>{e.target.disabled=true;try{const j=await frontFetch('/api/audio',{project_id:data.project_id,target_id:shot.shot_id||shot.id,kind,video_id:kind==='sync'?(selectedShotVideo(shot)?.id||selectedShotVideo(shot)?.job_id):undefined,prompt:c.prompt,lyrics:c.lyrics,duration:c.duration,bpm:c.bpm,language:'zh',port:Number(localStorage.getItem('frame-comfy-port')||8188)});jobs.unshift(j);draw(shot,container);toast('已提交本分镜'+kinds[kind]);}catch(error){toast(error.message);e.target.disabled=false;}};q('shotAudioStop')?.addEventListener('click',async()=>{try{const j=await frontFetch('/api/audio/'+running.id+'/cancel',{});jobs=jobs.map(x=>x.id===j.id?j:x);draw(shot,container);}catch(e){toast(e.message);}});container.querySelectorAll('[data-audio-adopt]').forEach(b=>b.onclick=()=>{c.activeId=b.dataset.audioAdopt;c.enabled=true;save();draw(shot,container);toast('已采用本分镜音频');});}
window.frameAudioStudio={config,draw,load,snapshot:(target)=>JSON.stringify({jobs:jobs.filter(j=>!target||j.target_id===target),status}),status:()=>status};let polling=false;setInterval(async()=>{if(polling||!jobs.some(busy))return;polling=true;try{let changed=false;for(const j of jobs.filter(busy)){const updated=await frontFetch('/api/audio/'+j.id);changed||=updated.status!==j.status;Object.assign(j,updated);}if(changed&&tab===2)render();if(changed&&tab===6)window.dispatchEvent(new Event('audio-jobs-updated'));}catch{}finally{polling=false;}},4000);render();})();
